#!/usr/bin/env python3
"""Payroll summary: python3 payroll.py INPUT_DIR OUTPUT_FILE (rules in docs/payroll-rules.md)."""
import csv
import gzip
import io
import json
import math
import os
import sys
from datetime import date, datetime, timedelta, timezone
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


# ---------------------------------------------------------------- helpers

def read_text(path):
    with open(path, "rb") as f:
        raw = f.read()
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    text = raw.decode("utf-8-sig")
    return text


def lines_of(text):
    out = []
    for ln in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if ln.strip() == "":
            continue
        out.append(ln)
    return out


def list_files(d):
    res = []
    if not os.path.isdir(d):
        return res
    for root, _dirs, files in os.walk(d):
        for fn in files:
            res.append(os.path.join(root, fn))
    res.sort()
    return res


def read_csv_file(path, delimiter=","):
    text = read_text(path)
    return list(csv.reader(lines_of(text), delimiter=delimiter))


def local_to_instant(naive, tz, want_dst=None):
    """Naive local datetime -> UTC epoch seconds. want_dst None: first occurrence."""
    d0 = naive.replace(tzinfo=tz, fold=0)
    d1 = naive.replace(tzinfo=tz, fold=1)
    if d0.utcoffset() == d1.utcoffset():
        d = d0
    elif want_dst is None:
        d = d0
    else:
        d = None
        for c in (d0, d1):
            if bool(c.dst()) == want_dst:
                d = c
                break
        if d is None:
            d = d0
    return int(d.timestamp()) if False else int((d.astimezone(UTC) - EPOCH).total_seconds())


def parse_iso_instant(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    d = d.astimezone(UTC)
    return int((d - EPOCH).total_seconds() // 1)


def floor_div_int(x):
    return int(math.floor(x))


# ---------------------------------------------------------------- site readers
# each reader yields (punch_id:str, employee:str, direction:'IN'|'OUT', instant:int)

def read_abbr_csv(path, tz):
    text = read_text(path)
    header = None
    for row in csv.reader(lines_of(text)):
        cells = [c.strip() for c in row]
        if "Badge" in cells and "Record" in cells:
            header = {name: i for i, name in enumerate(cells)}
            continue
        if header is None:
            continue
        try:
            badge = cells[header["Badge"]]
            punch = cells[header["Punch"]].upper()
            dstr = cells[header["Date"]]
            tstr = cells[header["Time"]]
            zone = cells[header["Zone"]] if "Zone" in header else ""
            rec = cells[header["Record"]]
        except (KeyError, IndexError):
            continue
        mo, da, yr = dstr.split("/")
        parts = tstr.split()
        hms = parts[0].split(":")
        h, m = int(hms[0]), int(hms[1])
        s = int(hms[2]) if len(hms) > 2 else 0
        if len(parts) > 1:
            ap = parts[1].upper()
            h = h % 12
            if ap == "PM":
                h += 12
        naive = datetime(int(yr), int(mo), int(da), h, m, s)
        z = zone.upper()
        want = True if z.endswith("DT") else (False if z.endswith("ST") else None)
        yield rec, badge, punch, local_to_instant(naive, tz, want)


def read_epoch_jsonl(path, tz):
    schema = 1
    for ln in lines_of(read_text(path)):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        if o.get("heartbeat") is True:
            continue
        if "schema" in o and len(o) == 1:
            schema = 2 if o["schema"] == 2 else 1
            continue
        try:
            if schema == 2:
                pid, emp, d, ms = o["punch_id"], o["employee"], o["direction"], o["epoch_ms"]
                inst = floor_div_int(Fraction(str(ms)) / 1000) if not isinstance(ms, int) else ms // 1000
            else:
                pid, emp, d = o["id"], o["emp"], o["dir"]
                if "ts_ms" in o:
                    ms = o["ts_ms"]
                    inst = ms // 1000 if isinstance(ms, int) else floor_div_int(ms / 1000.0)
                else:
                    ts = o["ts"]
                    inst = ts if isinstance(ts, int) else floor_div_int(ts)
        except KeyError:
            continue
        yield str(pid), str(emp), str(d).upper(), inst


def read_offset_csv(path, tz):
    for row in read_csv_file(path, ";"):
        cells = [c.strip() for c in row]
        if len(cells) < 4 or cells[0] == "punch_id":
            continue
        pid, emp, ev, ts = cells[:4]
        d = "IN" if ev.lower() == "clock_in" else "OUT"
        yield pid, emp, d, parse_iso_instant(ts)


def std_offset_seconds(tz, around):
    d = datetime.fromtimestamp(around, tz)
    return int((d.utcoffset() - (d.dst() or timedelta(0))).total_seconds())


def read_legacy_fixed(path, tz):
    default_off = None
    off = None
    for ln in lines_of(read_text(path)):
        t = ln[0]
        if t == "H":
            tok = ln[13:18].strip()
            if tok and tok[0] in "+-" and len(tok) == 5:
                sign = 1 if tok[0] == "+" else -1
                off = sign * (int(tok[1:3]) * 3600 + int(tok[3:5]) * 60)
            else:
                off = None
        elif t == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            dr = ln[15:16]
            dt = ln[16:30]
            naive = datetime(int(dt[0:4]), int(dt[4:6]), int(dt[6:8]), int(dt[8:10]), int(dt[10:12]), int(dt[12:14]))
            as_utc = int((naive.replace(tzinfo=UTC) - EPOCH).total_seconds())
            if off is None:
                # standard offset of the site zone (constant apart from rare zone-rule changes)
                o = std_offset_seconds(tz, as_utc)
                o2 = std_offset_seconds(tz, as_utc - o)
                o = o2
            else:
                o = off
            yield pid, "E" + badge, "IN" if dr == "I" else "OUT", as_utc - o


def read_de_tsv(path, tz):
    header = None
    for ln in lines_of(read_text(path)):
        cells = [c.strip() for c in ln.split("\t")]
        if "Ausweis" in cells and "Nr" in cells:
            header = {name: i for i, name in enumerate(cells)}
            continue
        if header is None:
            continue
        try:
            emp = cells[header["Ausweis"]]
            b = cells[header["Buchung"]].upper()
            dd, mm, yy = cells[header["Datum"]].split(".")
            hh, mi = cells[header["Uhrzeit"]].split(":")[:2]
            z = cells[header["Zeitzone"]].upper() if "Zeitzone" in header else ""
            nr = cells[header["Nr"]]
        except (KeyError, IndexError, ValueError):
            continue
        naive = datetime(int(yy), int(mm), int(dd), int(hh), int(mi))
        want = True if z == "MESZ" else (False if z == "MEZ" else None)
        yield nr, emp, "IN" if b == "K" else "OUT", local_to_instant(naive, tz, want)


def parse_local_dt(s):
    s = s.strip().replace("T", " ")
    return datetime.strptime(s[:19], "%Y-%m-%d %H:%M:%S")


def read_local_csv(path, tz):
    header = None
    for row in read_csv_file(path):
        cells = [c.strip() for c in row]
        if "employee_id" in cells and "punch_ref" in cells:
            header = {name: i for i, name in enumerate(cells)}
            continue
        if header is None:
            continue
        try:
            emp = cells[header["employee_id"]]
            d = cells[header["direction"]].upper()
            lt = cells[header["local_time"]]
            ref = cells[header["punch_ref"]]
        except (KeyError, IndexError):
            continue
        yield ref, emp, d, local_to_instant(parse_local_dt(lt), tz, None)


def read_local_jsonl(path, tz):
    for ln in lines_of(read_text(path)):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        p = o.get("punch") if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        yield (str(p["id"]), str(p["badge"]), str(p["type"]).upper(),
               local_to_instant(parse_local_dt(p["at"]), tz, None))


READERS = {
    "abbr-csv": read_abbr_csv,
    "epoch-jsonl": read_epoch_jsonl,
    "offset-csv": read_offset_csv,
    "legacy-fixed": read_legacy_fixed,
    "de-tsv": read_de_tsv,
    "local-csv": read_local_csv,
    "local-jsonl": read_local_jsonl,
}


# ---------------------------------------------------------------- main computation

def round_instant(inst, tz):
    off = int(datetime.fromtimestamp(inst, tz).utcoffset().total_seconds())
    s = inst + off
    r = ((s + 180) // 360) * 360
    return inst + (r - s)


def night_minutes(t_in, t_out, tz):
    """Minutes within [t_in, t_out) whose local time is in [22:00, 06:00)."""
    total = 0
    t = t_in

    def info(x):
        d = datetime.fromtimestamp(x, tz)
        return int(d.utcoffset().total_seconds())

    while t < t_out:
        off = info(t)
        loc = t + off
        sod = loc % 86400
        night = sod < 6 * 3600 or sod >= 22 * 3600
        if sod < 6 * 3600:
            nb = 6 * 3600
        elif sod < 22 * 3600:
            nb = 22 * 3600
        else:
            nb = 86400
        step = min(nb - sod, 3600, t_out - t)
        if info(t + step - 1) != off or info(t + step) != off and step < 3600 and False:
            # offset changes inside the chunk: go minute by minute
            step = min(60, t_out - t)
            if info(t + step - 1) != off:
                step = 1
        if night:
            total += step
        t += step
    return total // 60


def main(indir, outfile):
    with open(os.path.join(indir, "period.json")) as f:
        period = json.load(f)
    p_start = date.fromisoformat(period["start"])
    p_end = date.fromisoformat(period["end"])
    cutoff = parse_iso_instant(period["corrections_cutoff"])

    sites = {}
    with open(os.path.join(indir, "sites.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = {}
    with open(os.path.join(indir, "employees.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            employees[r["employee_id"].strip()] = r["home_site"].strip()

    rates = {}
    with open(os.path.join(indir, "rates.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            rates.setdefault(r["employee_id"].strip(), []).append(
                (date.fromisoformat(r["effective_from"].strip()), Fraction(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}   # (site, id) -> [employee, dir, instant]
    ever = set()
    for site, (tz, fmt) in sites.items():
        reader = READERS[fmt]
        for path in list_files(os.path.join(indir, "exports", site)):
            for pid, emp, d, inst in reader(path, tz):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = [emp, d, inst]

    # 2. corrections
    corrs = []
    for path in list_files(os.path.join(indir, "corrections")):
        for row in read_csv_file(path):
            cells = [c.strip() for c in row]
            if not cells or cells[0] == "correction_id":
                continue
            cells += [""] * (8 - len(cells))
            cid, issued, action, site, pid, emp, typ, tm = cells[:8]
            corrs.append((parse_iso_instant(issued), cid, action.lower(), site, pid, emp, typ, tm))
    corrs.sort(key=lambda c: (c[0], c[1]))
    applied = 0
    for issued, cid, action, site, pid, emp, typ, tm in corrs:
        if issued > cutoff:
            continue
        key = (site, pid)
        if action == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif action == "set":
            if key in punches and tm:
                punches[key][2] = parse_iso_instant(tm)
                applied += 1
        elif action == "add":
            if key not in ever and site in sites and tm:
                ever.add(key)
                punches[key] = [emp, typ.upper(), parse_iso_instant(tm)]
                applied += 1

    by_emp = {}
    for (site, pid), (emp, d, inst) in punches.items():
        if emp in employees:
            by_emp.setdefault(emp, []).append((inst, 0 if d == "OUT" else 1, site, pid, d))

    home_tz = {e: sites[h][0] for e, h in employees.items()}

    def workday(inst, emp):
        return datetime.fromtimestamp(inst, home_tz[emp]).date()

    in_period = lambda wd: p_start <= wd <= p_end

    results = {e: dict(shifts=0, paid=0, ot=0, night=0, pay=Fraction(0)) for e in employees}
    open_shifts = orphan_outs = dups = 0

    for emp, plist in by_emp.items():
        plist.sort(key=lambda p: (p[0], p[1], p[2], p[3]))
        # 3. duplicates
        kept = []
        last = None
        for p in plist:
            inst, _, site, pid, d = p
            rinst = round_instant(inst, sites[site][0])
            rec = (inst, site, pid, d, rinst)
            if last is not None and last[3] == d and inst - last[0] <= 300:
                if in_period(workday(rinst, emp)):
                    dups += 1
                continue
            kept.append(rec)
            last = rec
        # 5. pair
        shifts = []
        cur = None
        for rec in kept:
            inst, site, pid, d, rinst = rec
            if d == "IN":
                if cur is not None:
                    if in_period(workday(cur[4], emp)):
                        open_shifts += 1
                cur = rec
            else:
                if cur is None:
                    if in_period(workday(rinst, emp)):
                        orphan_outs += 1
                elif rinst - cur[4] <= 16 * 3600:
                    shifts.append((cur, rec))
                    cur = None
                else:
                    if in_period(workday(cur[4], emp)):
                        open_shifts += 1
                    if in_period(workday(rinst, emp)):
                        orphan_outs += 1
                    cur = None
        if cur is not None and in_period(workday(cur[4], emp)):
            open_shifts += 1

        # 6/7 minutes
        sh = []
        for i, o in shifts:
            wd = workday(i[4], emp)
            if not in_period(wd):
                continue
            worked = max(0, (o[4] - i[4]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(i[4], o[4], sites[i[1]][0]), paid)
            sh.append(dict(wd=wd, start=i[4], paid=paid, night=night))
        sh.sort(key=lambda s: s["start"])
        # 8 overtime
        day_cum = {}
        for s in sh:
            before = day_cum.get(s["wd"], 0)
            after = before + s["paid"]
            day_cum[s["wd"]] = after
            s["dot"] = max(0, after - 480) - max(0, before - 480)
        week_cum = {}
        for s in sh:
            wk = s["wd"] - timedelta(days=s["wd"].weekday())
            before = week_cum.get(wk, 0)
            nonot = s["paid"] - s["dot"]
            after = before + nonot
            week_cum[wk] = after
            s["wot"] = max(0, after - 2400) - max(0, before - 2400)
        res = results[emp]
        for s in sh:
            ot = s["dot"] + s["wot"]
            reg = s["paid"] - ot
            rate = None
            for eff, r in rates.get(emp, []):
                if eff <= s["wd"]:
                    rate = r
            if rate is None:
                rate = Fraction(0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * s["night"] / 60
            res["shifts"] += 1
            res["paid"] += s["paid"]
            res["ot"] += ot
            res["night"] += s["night"]
            res["pay"] += pay

    def money(fr):
        cents = math.floor(fr * 100 + Fraction(1, 2))
        return "%d.%02d" % divmod(cents, 100)

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tot_cents = 0
    for e in sorted(employees):
        r = results[e]
        g = money(r["pay"])
        tot_cents += int(g.replace(".", ""))
        out_emps[e] = {"shifts": r["shifts"], "paid_minutes": r["paid"], "overtime_minutes": r["ot"],
                       "night_minutes": r["night"], "gross": g}
        tot["shifts"] += r["shifts"]
        tot["paid_minutes"] += r["paid"]
        tot["overtime_minutes"] += r["ot"]
        tot["night_minutes"] += r["night"]
    tot["gross"] = "%d.%02d" % divmod(tot_cents, 100)

    summary = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": out_emps,
        "exceptions": {"open_shifts": open_shifts, "orphan_outs": orphan_outs,
                       "duplicates_dropped": dups, "corrections_applied": applied},
        "totals": tot,
    }
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w") as f:
        json.dump(summary, f, indent=1)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])

